sys_script.script:
(function executeRule(current, previous) {
    var FLAG_KEY = "x_2056099_indust_0_api_transition";
    var apiFlag = gs.getSession().getClientData(FLAG_KEY) || "";

    // Always clear the flag after reading to prevent reuse
    gs.getSession().putClientData(FLAG_KEY, "");

    // On INSERT: only allow if the API create flag is set
    if (current.operation() == "insert") {
        if (apiFlag == "create") return; // Legitimate API creation
        // Allow admin direct inserts for data management
        if (gs.hasRole("admin")) return;
        gs.addErrorMessage("Production schedules must be created through the Create Schedule API.");
        current.setAbortAction(true);
        return;
    }

    // On UPDATE: check if status changed
    var newStatus = current.getValue("status");
    var oldStatus = previous ? previous.getValue("status") : "";

    // If status did not change, allow the update (non-status field edits)
    if (newStatus == oldStatus) return;

    // Define the valid transition matrix
    var validTransitions = {
        "draft":      { "scheduled": "confirm",  "cancelled": "cancel" },
        "scheduled":  { "confirmed": "confirm",  "cancelled": "cancel" },
        "confirmed":  { "in_progress": "start",  "cancelled": "cancel" },
        "in_progress":{ "completed": "complete", "cancelled": "cancel" }
    };

    // Check if the transition is in the valid matrix
    var allowedTargets = validTransitions[oldStatus];
    if (!allowedTargets || !allowedTargets[newStatus]) {
        // Invalid transition path
        gs.addErrorMessage("Invalid schedule status transition: " + oldStatus + " → " + newStatus + ". This transition is not permitted.");
        current.setAbortAction(true);
        return;
    }

    // Valid transition path exists - now check if it came through the API
    var requiredFlag = allowedTargets[newStatus];
    if (apiFlag == requiredFlag) {
        return; // Legitimate API-driven transition
    }

    // Admin bypass for operational recovery
    if (gs.hasRole("admin")) return;

    // No valid API flag - block the direct write
    gs.addErrorMessage("Status transition " + oldStatus + " → " + newStatus + " must be performed through the authorized production API, not by direct record update.");
    current.setAbortAction(true);
})(current, previous);
